package net.battlespades.bot;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BooleanSupplier;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.support.StandardPorts;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotMessages.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
class BotWorkerIntegrationTest {
    @TempDir Path temp;
    private static final Vector START=new Vector(245.5,245.5,97.75),GOAL=new Vector(260.5,245.5,97.75);
    private static void until(BooleanSupplier done)throws Exception{long deadline=System.nanoTime()+8_000_000_000L;while(!done.getAsBoolean()){assertTrue(System.nanoTime()<deadline,"Bot worker timed out");Thread.sleep(1);}}
    private static Perception frame(long id,long epoch,long topology,int observer){var p=Player.basic(observer,1,2,5,true,true,START,START,new Vector(1,0,0),new Vector(0,0,0),100,6,50,10,100,true);return Perception.basic(id,epoch,topology,observer,1,id/8.,List.of(p));}
    private static Intent intent(Perception frame,List<Vector> path){return new Intent(frame.observerId(),frame.observerGeneration(),frame.frameId(),frame.mapEpoch(),frame.modeEpoch(),frame.topologyVersion(),frame.createdAt(),frame.createdAt()+.4,Movement.still(),null,-1,Action.none(),Priority.ROUTINE,false,false,GOAL,path,"fixture-controller",0,List.of());}
    @Test void workerOwnsRealSnapshotsCoalescesTerrainFramesAndDiagnosticsAndRecoversRejectedMap(){assertTimeoutPreemptively(Duration.ofSeconds(25),()->{
        Path repository=Path.of(System.getProperty("battlespades.applicationJar")).getParent().getParent().getParent().getParent();byte[] shipped=Files.readAllBytes(repository.resolve("maps/MayanJungle.vxl"));var cache=NavigationAtlas.decode(Files.readAllBytes(repository.resolve("maps/MayanJungle.botnav")),NavigationAtlas.sourceDigest(shipped));assertEquals(512,cache.width());assertTrue(cache.stats().dryColumns()>0);
        Path file=temp.resolve("First.vxl");StandardPorts.writeMap(file);byte[] bytes=Files.readAllBytes(file);Thread producer=Thread.currentThread();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var faults=new CopyOnWriteArrayList<String>();var seen=new CopyOnWriteArrayList<String>();var mutableEvents=new ArrayList<Object>();var fatalOnce=new AtomicBoolean();var workerWorld=new AtomicReference<BotNavigationWorld>();
        try(var worker=new BotWorker(world->{workerWorld.set(world);return new BotWorker.Brain(){
            public void resetForMap(long epoch){assertNotSame(producer,Thread.currentThread());seen.add("map:"+epoch);}public void resetBot(int id,int generation){seen.add("reset:"+id+":"+generation);}
            public Intent decide(Perception f){assertNotSame(producer,Thread.currentThread());seen.add(f.frameId()+":"+f.topologyVersion());if(f.frameId()==1){entered.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}}if(f.observerId()==99&&fatalOnce.compareAndSet(false,true))throw new LinkageError("controlled fatal worker exit");if(f.observerId()==13)throw new IllegalArgumentException("controlled observer failure");var route=world.corridor(START,GOAL,Set.of());if(route!=null)while(!route.done()){route.advance();if(route.deferred())break;}return intent(f,route==null?List.of():route.path());}
            public Map<String,Object> metrics(){mutableEvents.clear();mutableEvents.add("detached");return Map.of("events",mutableEvents,"map",world.epoch(),"health",world.blockHealth(400,400,40));}
        };},8,24,()->System.nanoTime()/1e9,(name,error)->faults.add(name))){
            worker.start(new MapSnapshot(7,10,bytes,"tdm","First",List.of(),"retail"));until(()->worker.status().running());assertThrows(IllegalStateException.class,()->workerWorld.get().ready());assertTrue(worker.submit(frame(1,7,10,9)));assertTrue(entered.await(5,TimeUnit.SECONDS));
            worker.publish(new VoxelChange(250,245,97,true,0,9),7,11);worker.publish(new VoxelChange(250,245,97,false,0,0),7,12);assertEquals(1,worker.status().pendingTerrainCells());assertTrue(worker.submit(frame(2,7,10,9)));assertTrue(worker.submit(frame(3,7,10,9)));assertFalse(worker.submit(frame(2,7,10,9)));assertTrue(worker.submit(frame(4,7,12,13)));assertTrue(worker.submit(frame(5,7,99,10)));release.countDown();until(()->worker.status().lastAcknowledgedFrameId()>=5);var intents=worker.drain(20);assertEquals(List.of(1L,3L),intents.stream().map(Intent::frameId).toList());assertEquals(12,intents.getLast().topologyVersion());assertFalse(intents.getLast().debugPath().isEmpty());assertTrue(seen.contains("3:12"));assertFalse(seen.contains("2:12"));assertTrue(seen.contains("reset:13:1"));assertEquals(1,faults.size());assertEquals(1,worker.status().droppedFrames());assertNull(worker.status().awaitingFrameId());assertTrue(worker.planningMetrics().get("granted").longValue()>0);
            var metrics=worker.behaviorMetrics();assertThrows(UnsupportedOperationException.class,()->((List<?>)metrics.get("events")).clear());worker.restart();until(()->worker.status().plannedRecycles()==1&&worker.status().running());assertEquals(1,worker.status().restarts());assertTrue(worker.submit(frame(6,7,10,9)));until(()->worker.status().lastAcknowledgedFrameId()>=6);assertEquals(12,worker.drain(10).getFirst().topologyVersion());assertEquals(List.of("detached"),metrics.get("events"));
            worker.publishMap(new MapSnapshot(8,0,new byte[]{1,2},"tdm","Broken",List.of(),"retail"));until(()->worker.status().snapshotRejections()==1);assertFalse(worker.status().running());Thread.sleep(40);assertEquals(1,worker.status().snapshotRejections());worker.publishMap(new MapSnapshot(9,0,bytes,"tdm","Recovered",List.of(),"retail"));until(()->worker.status().running());assertTrue(worker.submit(frame(7,9,0,9)));until(()->worker.status().lastAcknowledgedFrameId()>=7);assertEquals(9,worker.drain(10).getFirst().mapEpoch());assertEquals(1,worker.status().snapshotRejections());
            worker.publish(new VoxelChange(400,400,40,true,0,9),9,1);worker.submit(frame(8,9,0,99));until(worker::recoverIfStopped);until(()->worker.status().running());assertEquals(1,worker.status().crashRestarts());assertEquals(2,worker.status().restarts());worker.submit(frame(9,9,0,9));until(()->worker.status().lastAcknowledgedFrameId()>=9);var recovered=worker.drain(10).getFirst();assertEquals(9,recovered.mapEpoch());assertEquals(1,recovered.topologyVersion());assertEquals(9.,worker.behaviorMetrics().get("health"));assertTrue(faults.contains("bot worker fatal"));
        }finally{release.countDown();}
    });}
    @Test void processWorkerRunsRealBrainRecyclesRecoversKilledChildAndRetainsTerrain()throws Exception{assertTimeoutPreemptively(Duration.ofSeconds(40),()->{
        Path file=temp.resolve("Process.vxl");StandardPorts.writeMap(file);var faults=new CopyOnWriteArrayList<String>();var child=new AtomicReference<Process>();Process finalChild;
        try(var worker=BotWorker.process(8,24,()->System.nanoTime()/1e9,(name,error)->faults.add(name+": "+error),builder->{var process=builder.start();child.set(process);return process;})){
            worker.start(new MapSnapshot(1,0,Files.readAllBytes(file),"tdm","Process",List.of(),"retail"));until(()->worker.status().running());int first=worker.status().processId();var firstChild=child.get();assertNotEquals(ProcessHandle.current().pid(),first);worker.submit(frame(1,1,0,9));until(()->worker.status().lastAcknowledgedFrameId()>=1);assertFalse(worker.drain(10).isEmpty());
            worker.publish(new VoxelChange(400,400,40,true,0x123456,9),1,1);worker.restart();until(()->worker.status().running()&&worker.status().processId()!=first);assertFalse(firstChild.isAlive());assertEquals(1,worker.status().plannedRecycles());int recycled=worker.status().processId();var recycledChild=child.get();worker.submit(frame(2,1,0,9));until(()->worker.status().lastAcknowledgedFrameId()>=2);assertEquals(1,worker.drain(10).getFirst().topologyVersion());
            assertTrue(recycledChild.isAlive());recycledChild.destroyForcibly();worker.submit(frame(3,1,1,9));until(()->worker.status().crashRestarts()==1&&worker.status().running()&&worker.status().processId()!=recycled);assertFalse(recycledChild.isAlive());worker.submit(frame(4,1,1,9));until(()->worker.status().lastAcknowledgedFrameId()>=4);assertEquals(1,worker.drain(10).getLast().topologyVersion());assertFalse(faults.isEmpty());
            worker.publishMap(new MapSnapshot(2,0,new byte[]{1,2},"tdm","Broken",List.of(),"retail"));until(()->worker.status().snapshotRejections()==1);assertFalse(worker.status().running());worker.publishMap(new MapSnapshot(3,0,Files.readAllBytes(file),"tdm","Recovered",List.of(),"retail"));until(()->worker.status().running());worker.submit(frame(5,3,0,9));until(()->worker.status().lastAcknowledgedFrameId()>=5);assertEquals(3,worker.drain(10).getLast().mapEpoch());finalChild=child.get();
        }
        assertFalse(finalChild.isAlive());
    });}
    @Test void timedOutCloseRetainsExactWorkerUntilItStopsAndImmutableBoundariesRejectLiveObjects(){assertTimeoutPreemptively(Duration.ofSeconds(20),()->{
        Path file=temp.resolve("First.vxl");StandardPorts.writeMap(file);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var worker=new BotWorker(world->new BotWorker.Brain(){public void resetForMap(long epoch){}public void resetBot(int id,int generation){}public Map<String,Object> metrics(){return Map.of();}public Intent decide(Perception f){entered.countDown();while(release.getCount()>0)try{release.await();}catch(InterruptedException ignored){/* Controlled handler ignores cancellation to exercise retained shutdown. */}return intent(f,List.of());}},8,24,()->System.nanoTime()/1e9,(name,error)->{});
        var snapshot=new MapSnapshot(1,0,Files.readAllBytes(file),"tdm","First",List.of(),"retail");try{worker.start(snapshot);until(()->worker.status().running());worker.submit(frame(1,1,0,1));assertTrue(entered.await(5,TimeUnit.SECONDS));assertThrows(java.io.IOException.class,()->worker.close(.01));assertThrows(IllegalStateException.class,()->worker.start(snapshot));release.countDown();worker.close();assertFalse(worker.status().running());}finally{release.countDown();worker.close();}
        var source=new ArrayList<Object>(List.of("original"));var frozen=BotMessages.freeze(Map.of("nested",source));source.set(0,"changed");assertEquals(List.of("original"),frozen.get("nested"));assertThrows(IllegalArgumentException.class,()->BotMessages.freeze(Map.of("live",new Object())));assertThrows(IllegalArgumentException.class,()->BotMessages.freeze(Map.of("mutableNumber",new AtomicInteger(1))));
    });}
}
